//! Continuous integration for the Rust SDK for Dagger, built with the SDK itself.
//!
//! Every function runs inside the Dagger engine, so the same calls work from a laptop, a CI
//! runner, or a managed engine. Orchestration, secrets, and engine provisioning stay outside
//! the module, in `.dagger/engine.sh` and the pipelines that call it. So does publishing:
//! `package` prepares a release's archives, and `published` proves the release afterwards.

// Generated by `dagger generate`; regenerate after changing exported items. Its dispatch
// indexes arguments with `get(0)`.
#[allow(clippy::get_first)]
pub mod dagger_generated;

use std::collections::{BTreeMap, BTreeSet};

use dagger_generated::ModuleContext;
use dagger_sdk::{
    Container, ContainerWithExecOpts, Directory, File, ModuleError, Query, QueryError,
    QueryHttpOpts, ReturnType,
};
use serde_json::Value;

/// The runtime's digest-pinned builder, so CI compiles with the inputs module builds use.
const RUST_IMAGE: &str =
    "rust:1.97.1-bookworm@sha256:705e294093973d7c10e83400393dce7b3611f8e03e55a80af7fff6d02ae1affb";
/// The Go release the runtime's and rust-client-dev's `go.mod` files name.
const GO_IMAGE: &str = "golang:1.26.1-bookworm@sha256:ab3d6955bbc813a0f3fdf220c1d817dd89c0b3f283777db8ece4a32fe7858edd";
const CARGO_DENY_VERSION: &str = "0.19.9";
/// How much of a failed step's output an error keeps, from the end.
const OUTPUT_TAIL: usize = 16 * 1024;
const GATES_PASSED: &str = "cargo fmt, check, clippy, doc, test (all and no default features), \
    deny and the generated-output check, and the runtime and rust-client-dev Go tests passed";
/// The repository the acceptance installs the runtime from and builds the client against.
const REPOSITORY: &str = "github.com/tokeira/dagger-rust-sdk";
/// The release of the CLI the acceptance drives the engine with: the one the SDK targets.
const DAGGER_VERSION: &str = "1.0.0-beta.18";
/// Introduces the README's module block, which the acceptance runs as written.
const README_MARKER: &str = "<!-- The ci module's acceptance runs the module below as written. -->";
/// The manifest of the application that asks for a Rust client scope.
const APP_MANIFEST: &str =
    "[package]\nname = \"app\"\nversion = \"0.0.0\"\nedition = \"2024\"\npublish = false\n";
/// The crates a release publishes, in the order it publishes them: the SDK depends on the
/// macros crate at the same version.
const PUBLISHED: [&str; 2] = ["tokeira-dagger-sdk-macros", "tokeira-dagger-sdk"];
/// The largest archive crates.io accepts.
const ARCHIVE_LIMIT: i64 = 10 * 1024 * 1024;
/// How Cargo names crates.io as a package's source.
const CRATES_IO: &str = "registry+https://github.com/rust-lang/crates.io-index";

#[dagger_sdk::object(root, rename = "Ci")]
pub struct Ci {
    #[dagger(state)]
    source: Directory,
}

#[dagger_sdk::methods]
impl Ci {
    #[dagger(constructor, rename = "ci")]
    pub fn new(
        #[dagger(
            doc = "Repository checkout; defaults to the workspace root.",
            default_path = "/",
            ignore = [".git", ".claude", "**/target"]
        )]
        source: Directory,
    ) -> Ci {
        Ci { source }
    }

    /// Runs the engine-free acceptance of docs/maintaining.md, section 5: the Cargo gates
    /// and the Go tests, concurrently.
    #[dagger(function)]
    pub async fn gates(
        &self,
        #[dagger(context)] context: ModuleContext,
    ) -> Result<String, ModuleError> {
        let dag = context.query();
        let cargo = cargo_gates(dag, &self.source).await?;
        let go = go_gates(dag, &self.source);
        tokio::try_join!(cargo.sync(), go.sync()).map_err(step_failure)?;
        Ok(GATES_PASSED.to_owned())
    }

    /// Runs the stock-engine acceptance of docs/engine-integration.md for a pushed commit:
    /// the runtime installed from it, a module initialized, regenerated, loaded and called,
    /// a plain client, a refused client scope, and the README module's test and build. It
    /// needs an engine of the release the commit targets.
    #[dagger(function)]
    pub async fn acceptance(
        &self,
        #[dagger(context)] context: ModuleContext,
        #[dagger(doc = "Full hash of a commit pushed to github.com/tokeira/dagger-rust-sdk.")]
        commit: String,
    ) -> Result<String, ModuleError> {
        let dag = context.query();
        let (tree, engine) = pushed(dag, &commit).await?;
        // The line `dagger module init` must write into the module's Cargo.toml.
        let pin = json_file(&tree, "runtime/assets/sdk-dependency.json").await?;
        let dependency = format!(
            "dagger-sdk = {{ package = \"tokeira-dagger-sdk\", git = \"{}\", rev = \"{}\" }}",
            string_field(&pin, "runtime/assets/sdk-dependency.json", "repository")?,
            string_field(&pin, "runtime/assets/sdk-dependency.json", "revision")?,
        );

        let cli = dagger_cli(dag).await?;
        // From the checkout: the module's own loaded source would regenerate it, which fails
        // when the committed generated files come from an engine of another platform.
        let fixtures = self.source.directory(".dagger/modules/ci/acceptance");
        let runtime = format!("{REPOSITORY}/runtime@{commit}");
        tokio::try_join!(
            module_flows(&cli, &fixtures, &runtime, &dependency),
            plain_client(dag, &cli, &fixtures, &tree, &engine),
            readme_module(&cli, &fixtures, &tree, &runtime),
        )?;
        Ok(format!(
            "{commit} passed on {engine}: the runtime installed; a module initialized, \
             regenerated, loaded and answered calls; a plain client made Void calls and exported \
             an image; a Rust client scope was refused; and the README module's test and build \
             passed"
        ))
    }

    /// Packages the crates a release publishes, from a pushed commit, as `cargo publish`
    /// will: one `cargo package` verifies each crate by building it from its archive. An
    /// application outside the repository then builds and runs against the archives.
    /// Returns the archives, their SHA256SUMS, and each crate's file list to review before
    /// publishing. It needs an engine of the release the commit targets.
    #[dagger(function)]
    pub async fn package(
        &self,
        #[dagger(context)] context: ModuleContext,
        #[dagger(
            doc = "Full hash of the release commit, pushed to github.com/tokeira/dagger-rust-sdk."
        )]
        commit: String,
    ) -> Result<Directory, ModuleError> {
        let dag = context.query();
        let (tree, engine) = pushed(dag, &commit).await?;
        let version = release_version(dag, &tree).await?;
        unpublished(dag, &version).await?;
        let release = archives(dag, &tree, &commit, &version).await?;
        consumer(dag, &self.source, &engine, &version, Some(&release)).await?;
        Ok(release)
    }

    /// Proves a release on crates.io: each archive crates.io serves is the one `package`
    /// returned, and an application that depends on the version alone resolves exactly the
    /// published crates from crates.io, builds, and runs. It needs an engine of the release
    /// the version targets.
    #[dagger(function)]
    pub async fn published(
        &self,
        #[dagger(context)] context: ModuleContext,
        #[dagger(doc = "The SHA256SUMS file that `package` returned for the release.")] sums: File,
    ) -> Result<String, ModuleError> {
        let dag = context.query();
        let sums = sums.contents().await?;
        let (version, archives) = release_sums(&sums)?;
        for (name, sha256) in &archives {
            // The engine refuses a download whose digest differs.
            dag.http_opts(
                format!("https://static.crates.io/crates/{name}/{name}-{version}.crate"),
                &QueryHttpOpts::default().with_checksum(format!("sha256:{sha256}")),
            )
            .size()
            .await
            .map_err(|error| {
                ModuleError::new(format!(
                    "crates.io does not serve the packaged {name} {version}: {}",
                    ModuleError::from(error).message()
                ))
            })?;
        }
        let engine = dag.version().await?;
        consumer(dag, &self.source, &engine, &version, None).await?;
        Ok(format!(
            "{version} is on crates.io as packaged: both archives match SHA256SUMS, and an \
             application that depends on tokeira-dagger-sdk {version} alone resolved both crates \
             from crates.io, built, and ran on {engine}"
        ))
    }
}

/// The tree of a commit pushed to the repository, with its `.git` directory, once the
/// commit is checked to target the engine that runs this module; and that engine's version.
async fn pushed(dag: &Query, commit: &str) -> Result<(Directory, String), ModuleError> {
    if commit.len() != 40
        || !commit
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
    {
        return Err(ModuleError::new(format!(
            "{commit:?} is not a full lowercase commit hash"
        )));
    }
    let tree = dag
        .git(format!("https://{REPOSITORY}"))
        .commit(commit)
        .tree();
    // The engine's error for a commit it cannot fetch does not name the usual cause.
    tree.sync().await.map_err(|error| {
        let cause = ModuleError::from(error);
        ModuleError::new(format!(
            "cannot fetch {commit} from https://{REPOSITORY}; push it first: {}",
            cause.message()
        ))
    })?;
    let target = json_file(&tree, "codegen/target.json").await?;
    let engine_version = string_field(&target, "codegen/target.json", "engine_version")?;
    let revision = string_field(&target, "codegen/target.json", "dagger_revision")?;
    if engine_version != format!("v{DAGGER_VERSION}") {
        return Err(ModuleError::new(format!(
            "{commit} targets {engine_version}, but this module drives v{DAGGER_VERSION}"
        )));
    }
    let expected = format!("{engine_version}+{}", revision.get(..8).unwrap_or(revision));
    let engine = dag.version().await?;
    if engine != expected {
        return Err(ModuleError::new(format!(
            "{commit} needs a {expected} engine; this one is {engine}"
        )));
    }
    Ok((tree, engine))
}

/// The Cargo half of the gates, in one container so the steps share their build output.
async fn cargo_gates(dag: &Query, source: &Directory) -> Result<Container, ModuleError> {
    let (triple, sha256) = match dag.default_platform().await?.as_str() {
        "linux/amd64" => (
            "x86_64-unknown-linux-musl",
            "f1f8eedc2a3ac297c540873f93785d4104b102c0079506b2a6b3221b7ec956af",
        ),
        "linux/arm64" => (
            "aarch64-unknown-linux-musl",
            "32580dcc2bc13fbeeb7c50edc38ef99c3b9ce9569a1d07a96e11b3b941f3e72e",
        ),
        other => {
            return Err(ModuleError::new(format!(
                "no pinned cargo-deny for {other}"
            )));
        }
    };
    let archive = format!("cargo-deny-{CARGO_DENY_VERSION}-{triple}");
    let binary = format!("{archive}/cargo-deny");
    // The engine verifies the digest before the archive reaches the container.
    let deny = dag.http_opts(
        format!(
            "https://github.com/EmbarkStudios/cargo-deny/releases/download/{CARGO_DENY_VERSION}/{archive}.tar.gz"
        ),
        &QueryHttpOpts::default().with_checksum(format!("sha256:{sha256}")),
    );
    let registry = dag.cache_volume("cargo-registry");
    let target = dag.cache_volume("ci-cargo-target");
    Ok(dag
        .container()
        .from(RUST_IMAGE)
        .with_exec(vec!["rustup", "component", "add", "clippy", "rustfmt"])
        .with_mounted_file("/tmp/cargo-deny.tar.gz", deny)
        .with_exec(vec![
            "tar",
            "-xzf",
            "/tmp/cargo-deny.tar.gz",
            "-C",
            "/usr/local/bin",
            "--strip-components=1",
            binary.as_str(),
        ])
        .with_mounted_cache(registry, "/usr/local/cargo/registry")
        .with_mounted_cache(target, "/cargo-target")
        .with_env_variable("CARGO_TARGET_DIR", "/cargo-target")
        .with_mounted_directory("/src", source.clone())
        .with_workdir("/src")
        .with_exec(vec!["cargo", "fmt", "--all", "--check"])
        .with_exec(vec![
            "cargo",
            "check",
            "--workspace",
            "--all-features",
            "--locked",
        ])
        .with_exec(vec![
            "cargo",
            "clippy",
            "--workspace",
            "--all-targets",
            "--all-features",
            "--locked",
            "--",
            "-D",
            "warnings",
        ])
        // Warnings fail documentation only; doctests keep the ordinary flags.
        .with_env_variable("RUSTDOCFLAGS", "-D warnings")
        .with_exec(vec![
            "cargo",
            "doc",
            "--workspace",
            "--all-features",
            "--no-deps",
            "--locked",
        ])
        .without_env_variable("RUSTDOCFLAGS")
        .with_exec(vec![
            "cargo",
            "test",
            "--workspace",
            "--all-features",
            "--locked",
            "--no-fail-fast",
        ])
        .with_exec(vec![
            "cargo",
            "test",
            "-p",
            "tokeira-dagger-sdk",
            "--no-default-features",
            "--locked",
            "--no-fail-fast",
        ])
        .with_exec(vec!["cargo", "deny", "check"])
        .with_exec(vec![
            "cargo",
            "run",
            "-p",
            "dagger-bootstrap",
            "--bin",
            "dagger-rust",
            "--locked",
            "--",
            "generate",
            "--workspace",
            ".",
            "--check",
        ]))
}

/// The Go half: the runtime's adapter and the rust-client-dev engine-free suites.
fn go_gates(dag: &Query, source: &Directory) -> Container {
    dag.container()
        .from(GO_IMAGE)
        .with_mounted_cache(dag.cache_volume("ci-go-modules"), "/go/pkg/mod")
        .with_mounted_cache(dag.cache_volume("ci-go-build"), "/root/.cache/go-build")
        .with_mounted_directory("/src", source.clone())
        .with_workdir("/src/runtime")
        .with_exec(vec!["go", "vet", "./..."])
        .with_exec(vec!["go", "test", "-count=1", "./internal/metadata"])
        // The generated bindings read the session when the package loads; nothing connects.
        .with_env_variable("DAGGER_SESSION_PORT", "1")
        .with_env_variable("DAGGER_SESSION_TOKEN", "placeholder")
        .with_exec(vec!["go", "test", "-count=1", "."])
        .without_env_variable("DAGGER_SESSION_PORT")
        .without_env_variable("DAGGER_SESSION_TOKEN")
        .with_workdir("/src/.dagger/modules/rust-client-dev")
        .with_exec(vec![
            "go",
            "test",
            "-count=1",
            ".",
            "./internal/enginefixture",
            "./internal/enginefree",
        ])
}

/// A Rust container with the target release's CLI, for the `dagger` commands that the
/// acceptance runs as new sessions of this engine.
async fn dagger_cli(dag: &Query) -> Result<Container, ModuleError> {
    let (platform, sha256) = match dag.default_platform().await?.as_str() {
        "linux/amd64" => (
            "linux_amd64",
            "5326f48825b64008705290cb2a8109c28e4a88d341ef765be8234860acf32fdb",
        ),
        "linux/arm64" => (
            "linux_arm64",
            "abcc2e70154498e7933758e7d81b3be79f7a5699d30b0d04ea33ed70d6edf827",
        ),
        other => {
            return Err(ModuleError::new(format!(
                "no pinned Dagger CLI for {other}"
            )));
        }
    };
    let archive = dag.http_opts(
        format!(
            "https://dl.dagger.io/dagger/releases/{DAGGER_VERSION}/dagger_v{DAGGER_VERSION}_{platform}.tar.gz"
        ),
        &QueryHttpOpts::default().with_checksum(format!("sha256:{sha256}")),
    );
    Ok(dag
        .container()
        .from(RUST_IMAGE)
        .with_mounted_file("/tmp/dagger.tar.gz", archive)
        .with_exec(vec![
            "tar",
            "-xzf",
            "/tmp/dagger.tar.gz",
            "-C",
            "/usr/local/bin",
            "dagger",
        ])
        .with_env_variable("DAGGER_NO_NAG", "1")
        .with_env_variable("GIT_AUTHOR_NAME", "acceptance")
        .with_env_variable("GIT_AUTHOR_EMAIL", "acceptance@example.invalid")
        .with_env_variable("GIT_COMMITTER_NAME", "acceptance")
        .with_env_variable("GIT_COMMITTER_EMAIL", "acceptance@example.invalid"))
}

/// Steps 1 to 5 and 7 of the acceptance: install the runtime, initialize a module, load it
/// before regeneration, regenerate it twice, call its exports, and refuse a client scope.
async fn module_flows(
    cli: &Container,
    fixtures: &Directory,
    runtime: &str,
    dependency: &str,
) -> Result<(), ModuleError> {
    let workspace = dagger(&repository(cli, "/ws"), &["install", runtime]);
    let workspace = dagger(
        &workspace,
        &["-y", "module", "init", "rust", "--name", "gate"],
    );
    let manifest = workspace
        .file("/ws/.dagger/modules/gate/Cargo.toml")
        .contents()
        .await
        .map_err(step_failure)?;
    if !manifest.lines().any(|line| line == dependency) {
        return Err(check_failed(
            "dagger module init",
            format!("the module's Cargo.toml lacks `{dependency}`:\n{manifest}"),
        ));
    }
    let workspace = commit_all(&workspace, "initialize gate module")
        .with_file(
            "/ws/.dagger/modules/gate/src/lib.rs",
            fixtures.file("gate.rs"),
        )
        .with_new_file("rust module gate\n", "/ws/gate-input/note.txt");
    let note = ["call", "gate", "note", "--source", "gate-input", "contents"];
    refused(&workspace, &note, "run `dagger generate`").await?;

    let workspace = commit_all(
        &dagger(&workspace, &["generate", "-y"]),
        "regenerate gate module",
    );
    let workspace = dagger(&workspace, &["generate", "-y"]);
    unchanged(&workspace, "a second dagger generate").await?;
    let attributes = workspace
        .file("/ws/.dagger/modules/gate/.gitattributes")
        .contents()
        .await
        .map_err(step_failure)?;
    if attributes.contains("/.dagger/modules/gate/") {
        return Err(check_failed(
            "dagger generate",
            format!("the module's .gitattributes names paths outside it:\n{attributes}"),
        ));
    }
    tokio::try_join!(
        prints(&workspace, &note, "rust module gate"),
        prints(
            &workspace,
            &["call", "gate", "count", "--source", "gate-input"],
            "1"
        ),
        client_scope_refused(&workspace),
    )?;
    Ok(())
}

/// Step 7: adding a Rust client scope is refused before anything is written.
async fn client_scope_refused(workspace: &Container) -> Result<(), ModuleError> {
    let app = commit_all(
        &workspace
            .with_new_file(APP_MANIFEST, "/ws/app/Cargo.toml")
            .with_new_file("fn main() {}\n", "/ws/app/src/main.rs"),
        "client app",
    )
    .with_workdir("/ws/app/src");
    let refusal = refused(
        &app,
        &[
            "-y",
            "module",
            "client",
            "add",
            "../../.dagger/modules/gate",
        ],
        "the Rust SDK does not generate module clients",
    )
    .await?;
    unchanged(&refusal, "the refused client scope").await?;
    let config = refusal
        .file("/ws/dagger.toml")
        .contents()
        .await
        .map_err(step_failure)?;
    if config.contains("clients") {
        return Err(check_failed(
            "the refused client scope",
            format!("dagger.toml records it:\n{config}"),
        ));
    }
    Ok(())
}

/// Step 6: a plain client, built from the commit, runs under `dagger run`, makes Void calls,
/// and exports an image.
async fn plain_client(
    dag: &Query,
    cli: &Container,
    fixtures: &Directory,
    tree: &Directory,
    engine: &str,
) -> Result<(), ModuleError> {
    let client = cli
        .with_mounted_cache(
            dag.cache_volume("cargo-registry"),
            "/usr/local/cargo/registry",
        )
        .with_directory("/sdk", tree.clone())
        .with_directory("/client", fixtures.directory("client"));
    // `Workspace.export` needs a Git workspace.
    let client = repository(&client, "/client")
        .with_exec(vec!["cargo", "generate-lockfile", "--quiet"])
        .with_exec(vec!["cargo", "build", "--quiet", "--locked"]);
    let run = dagger(&client, &["run", "cargo", "run", "--quiet", "--locked"]);
    let output = run.stdout().await.map_err(step_failure)?;
    let expected = format!("ACCEPTANCE-CLIENT-OK {engine}");
    if !output.lines().any(|line| line == expected) {
        return Err(check_failed(
            "the plain client",
            format!("printed no `{expected}`:\n{}", tail(&output)),
        ));
    }
    let image = run
        .with_exec(vec!["tar", "-tf", "canary.tar"])
        .stdout()
        .await
        .map_err(step_failure)?;
    if !image.lines().any(|line| line == "index.json") {
        return Err(check_failed(
            "the plain client",
            format!("exported no OCI image:\n{image}"),
        ));
    }
    Ok(())
}

/// The README's module, as readers copy it: generated into a sample service, then its
/// test against PostgreSQL and its build. Its publish needs a registry, so it is checked by
/// hand.
async fn readme_module(
    cli: &Container,
    fixtures: &Directory,
    tree: &Directory,
    runtime: &str,
) -> Result<(), ModuleError> {
    let readme = tree.file("README.md").contents().await?;
    let module = marked_module(&readme)?;
    let service = repository(
        &cli.with_directory("/api", fixtures.directory("api")),
        "/api",
    );
    let service = dagger(&service, &["install", runtime]);
    let service = commit_all(
        &dagger(&service, &["-y", "module", "init", "rust", "--name", "ci"]),
        "initialize ci module",
    )
    .with_new_file(module, "/api/.dagger/modules/ci/src/lib.rs");
    let service = commit_all(
        &dagger(&service, &["generate", "-y"]),
        "ci module functions",
    );

    let test = async {
        let report = dagger(&service, &["call", "ci", "test"])
            .stdout()
            .await
            .map_err(step_failure)?;
        if report.contains("test database_accepts_connections ... ok") {
            Ok(())
        } else {
            Err(check_failed(
                "dagger call ci test",
                format!("the database test did not pass:\n{}", tail(&report)),
            ))
        }
    };
    let build = prints(
        &service,
        &[
            "call",
            "ci",
            "build",
            "with-exec",
            "--args=/usr/local/bin/api",
            "stdout",
        ],
        "api 0.1.0",
    );
    tokio::try_join!(test, build)?;
    Ok(())
}

/// The module block that `README_MARKER` introduces in the README.
fn marked_module(readme: &str) -> Result<String, ModuleError> {
    let unmarked =
        || ModuleError::new(format!("README.md has no Rust block after {README_MARKER}"));
    let (_, marked) = readme.split_once(README_MARKER).ok_or_else(unmarked)?;
    let (_, block) = marked.split_once("```rust\n").ok_or_else(unmarked)?;
    let (module, _) = block.split_once("\n```").ok_or_else(unmarked)?;
    Ok(format!("{module}\n"))
}

/// The pinned toolchain with Cargo's download cache.
fn rust(dag: &Query) -> Container {
    dag.container().from(RUST_IMAGE).with_mounted_cache(
        dag.cache_volume("cargo-registry"),
        "/usr/local/cargo/registry",
    )
}

/// The version a commit releases. The crates it publishes must be exactly `PUBLISHED`, at
/// one version, each with the metadata crates.io displays.
async fn release_version(dag: &Query, tree: &Directory) -> Result<String, ModuleError> {
    let metadata = rust(dag)
        .with_directory("/src", tree.clone())
        .with_workdir("/src")
        .with_exec(vec![
            "cargo",
            "metadata",
            "--format-version",
            "1",
            "--no-deps",
            "--locked",
        ])
        .stdout()
        .await
        .map_err(step_failure)?;
    let metadata: Value = serde_json::from_str(&metadata)
        .map_err(|error| ModuleError::new(format!("cargo metadata: {error}")))?;
    let mut published = BTreeMap::new();
    for package in metadata["packages"].as_array().into_iter().flatten() {
        // `publish` is null when any registry may take the crate, and empty for
        // `publish = false`.
        if package["publish"].as_array().is_some_and(Vec::is_empty) {
            continue;
        }
        let name = package["name"].as_str().unwrap_or_default();
        for field in [
            "description",
            "license",
            "repository",
            "readme",
            "rust_version",
        ] {
            if package[field].as_str().is_none_or(str::is_empty) {
                return Err(ModuleError::new(format!(
                    "{name} has no {field}, which crates.io displays"
                )));
            }
        }
        let version = package["version"].as_str().unwrap_or_default();
        published.insert(name.to_owned(), version.to_owned());
    }
    let expected: BTreeSet<&str> = PUBLISHED.into_iter().collect();
    if !published.keys().map(String::as_str).eq(expected) {
        return Err(ModuleError::new(format!(
            "the workspace publishes {:?}, not {PUBLISHED:?}",
            published.keys().collect::<Vec<_>>()
        )));
    }
    let versions: BTreeSet<&String> = published.values().collect();
    match versions.into_iter().collect::<Vec<_>>()[..] {
        [version] => Ok(version.clone()),
        _ => Err(ModuleError::new(format!(
            "the published crates must share one version: {published:?}"
        ))),
    }
}

/// Refuses a version crates.io already lists: a published version is never replaced, so a
/// fix needs a new one.
async fn unpublished(dag: &Query, version: &str) -> Result<(), ModuleError> {
    // Never cached, so every run reads the index afresh.
    let now = dag.current_timestamp().await?;
    for name in PUBLISHED {
        let url = format!("https://index.crates.io/{}", sparse_index_path(name));
        let lookup = dag
            .container()
            .from(RUST_IMAGE)
            .with_env_variable("LOOKED_UP_AT", now.as_str())
            .with_exec(vec![
                "curl",
                "--silent",
                "--show-error",
                "--output",
                "/tmp/index",
                "--write-out",
                "%{http_code}",
                url.as_str(),
            ]);
        match lookup.stdout().await.map_err(step_failure)?.as_str() {
            // crates.io has never published the crate.
            "404" => {}
            "200" => {
                let index = lookup.file("/tmp/index").contents().await?;
                // Each line of the index describes one published version.
                if index.lines().any(|line| {
                    serde_json::from_str::<Value>(line).is_ok_and(|entry| entry["vers"] == version)
                }) {
                    return Err(ModuleError::new(format!(
                        "crates.io already has {name} {version}; a release needs a new version"
                    )));
                }
            }
            status => {
                return Err(ModuleError::new(format!("{url} answered HTTP {status}")));
            }
        }
    }
    Ok(())
}

/// Where the crates.io sparse index lists a crate.
fn sparse_index_path(name: &str) -> String {
    match name.len() {
        1 => format!("1/{name}"),
        2 => format!("2/{name}"),
        3 => format!("3/{}/{name}", &name[..1]),
        _ => format!("{}/{}/{name}", &name[..2], &name[2..4]),
    }
}

/// Packages the published crates in one `cargo package`, which verifies each by building
/// it from its archive, the SDK against the packaged macros crate. Returns the archives,
/// their SHA256SUMS, and each crate's `cargo package --list`, once each archive is within
/// crates.io's limit and records the clean commit it came from.
async fn archives(
    dag: &Query,
    tree: &Directory,
    commit: &str,
    version: &str,
) -> Result<Directory, ModuleError> {
    let mut command = vec!["cargo", "package", "--locked"];
    for name in PUBLISHED {
        command.extend(["-p", name]);
    }
    let packaged = rust(dag)
        .with_directory("/src", tree.clone())
        .with_workdir("/src")
        .with_exec(command);
    // The tests the archives leave out each draw a notice; any other warning stops here.
    let log = packaged.stderr().await.map_err(step_failure)?;
    let warnings: Vec<&str> = log
        .lines()
        .filter(|line| {
            line.starts_with("warning:")
                && !(line.starts_with("warning: ignoring test ")
                    && line.ends_with(" is not included in the published package"))
        })
        .collect();
    if !warnings.is_empty() {
        return Err(check_failed(
            "cargo package",
            format!("warned:\n{}", warnings.join("\n")),
        ));
    }

    let mut release = packaged.with_exec(vec!["mkdir", "/release"]);
    for name in PUBLISHED {
        let files = packaged
            .with_exec(vec!["cargo", "package", "--locked", "--list", "-p", name])
            .stdout()
            .await
            .map_err(step_failure)?;
        let archive = format!("target/package/{name}-{version}.crate");
        release = release
            .with_new_file(files, format!("/release/{name}-{version}.files"))
            .with_exec(vec!["cp", archive.as_str(), "/release/"]);
    }
    let release = release.with_workdir("/release").with_exec(vec![
        "sh",
        "-c",
        "sha256sum *.crate > SHA256SUMS",
    ]);
    for name in PUBLISHED {
        let archive = format!("{name}-{version}.crate");
        let size = release.file(format!("/release/{archive}")).size().await?;
        if size > ARCHIVE_LIMIT {
            return Err(check_failed(
                &archive,
                format!("is {size} bytes, over crates.io's limit of {ARCHIVE_LIMIT}"),
            ));
        }
        let record = release
            .with_exec(vec![
                "tar",
                "-xzOf",
                archive.as_str(),
                format!("{name}-{version}/.cargo_vcs_info.json").as_str(),
            ])
            .stdout()
            .await
            .map_err(step_failure)?;
        let record: Value = serde_json::from_str(&record)
            .map_err(|error| check_failed(&archive, format!("has no VCS record: {error}")))?;
        if record["git"]["sha1"] != commit || record["git"]["dirty"] == true {
            return Err(check_failed(
                &archive,
                format!("records {record}, not the clean commit {commit}"),
            ));
        }
    }
    Ok(release.directory("/release"))
}

/// Builds the consumer application against the published crates, from the archives
/// `package` returned when given them and from crates.io otherwise, checks where its crates
/// came from, and runs it as a new session of this engine.
async fn consumer(
    dag: &Query,
    source: &Directory,
    engine: &str,
    version: &str,
    archives: Option<&Directory>,
) -> Result<(), ModuleError> {
    let mut app = dagger_cli(dag)
        .await?
        .with_mounted_cache(
            dag.cache_volume("cargo-registry"),
            "/usr/local/cargo/registry",
        )
        .with_new_file(
            consumer_manifest(version, archives.is_some()),
            "/consumer/Cargo.toml",
        )
        .with_file(
            "/consumer/src/main.rs",
            source.file(".dagger/modules/ci/consumer/main.rs"),
        );
    if let Some(archives) = archives {
        app = app
            .with_directory("/release", archives.clone())
            .with_exec(vec!["mkdir", "/archives"]);
        for name in PUBLISHED {
            let archive = format!("/release/{name}-{version}.crate");
            app = app.with_exec(vec!["tar", "-xzf", archive.as_str(), "-C", "/archives"]);
        }
    }
    let app = app
        .with_workdir("/consumer")
        .with_exec(vec!["cargo", "generate-lockfile"]);
    let metadata = app
        .with_exec(vec![
            "cargo",
            "metadata",
            "--format-version",
            "1",
            "--locked",
        ])
        .stdout()
        .await
        .map_err(step_failure)?;
    resolved(&metadata, version, archives.is_some())?;
    let built = app.with_exec(vec!["cargo", "build", "--locked"]);
    let output = dagger(&built, &["run", "cargo", "run", "--locked", "--quiet"])
        .stdout()
        .await
        .map_err(step_failure)?;
    let expected = format!("CONSUMER-OK {engine} hello consumer");
    if output.lines().any(|line| line == expected) {
        Ok(())
    } else {
        Err(check_failed(
            "the consumer",
            format!("printed no `{expected}`:\n{}", tail(&output)),
        ))
    }
}

/// The consumer's manifest: the SDK by version alone, as an application depends on it, in a
/// workspace of its own. With `archives`, the published crates resolve from the unpacked
/// archives instead of crates.io.
fn consumer_manifest(version: &str, archives: bool) -> String {
    let mut manifest = format!(
        "[package]\nname = \"consumer\"\nversion = \"0.0.0\"\nedition = \"2024\"\n\
         publish = false\n\n[workspace]\n\n[dependencies]\n\
         tokeira-dagger-sdk = \"={version}\"\n\
         tokio = {{ version = \"1\", features = [\"macros\", \"rt-multi-thread\"] }}\n"
    );
    if archives {
        manifest.push_str("\n[patch.crates-io]\n");
        for name in PUBLISHED {
            manifest.push_str(&format!(
                "{name} = {{ path = \"/archives/{name}-{version}\" }}\n"
            ));
        }
    }
    manifest
}

/// Checks the consumer's resolved crates: each published crate once, at the release
/// version, from the archives or from crates.io as asked, and every other crate from
/// crates.io, so nothing comes from Git or a path.
fn resolved(metadata: &str, version: &str, archives: bool) -> Result<(), ModuleError> {
    let metadata: Value = serde_json::from_str(metadata)
        .map_err(|error| ModuleError::new(format!("the consumer's cargo metadata: {error}")))?;
    let packages: Vec<&Value> = metadata["packages"]
        .as_array()
        .into_iter()
        .flatten()
        .collect();
    for package in &packages {
        let name = package["name"].as_str().unwrap_or_default();
        let local = name == "consumer" || (archives && PUBLISHED.contains(&name));
        let source = package["source"].as_str();
        let expected = match source {
            None => local,
            Some(source) => !local && source == CRATES_IO,
        };
        if !expected {
            return Err(check_failed(
                "the consumer",
                format!(
                    "resolved {name} {} from {}",
                    package["version"],
                    source.unwrap_or("a path")
                ),
            ));
        }
    }
    for name in PUBLISHED {
        let versions: Vec<&str> = packages
            .iter()
            .filter(|package| package["name"] == name)
            .filter_map(|package| package["version"].as_str())
            .collect();
        if versions != [version] {
            return Err(check_failed(
                "the consumer",
                format!("resolved {name} at {versions:?}, not {version}"),
            ));
        }
    }
    Ok(())
}

/// The release version and each published crate's SHA-256, read from a SHA256SUMS that
/// `package` returned.
fn release_sums(sums: &str) -> Result<(String, Vec<(&'static str, String)>), ModuleError> {
    let unexpected =
        |line: &str| ModuleError::new(format!("SHA256SUMS has an unexpected line: {line:?}"));
    let mut version: Option<&str> = None;
    let mut archives = Vec::new();
    for line in sums.lines() {
        let (sha256, file) = line.split_once("  ").ok_or_else(|| unexpected(line))?;
        let (name, release) = file
            .strip_suffix(".crate")
            .and_then(|archive| {
                PUBLISHED.into_iter().find_map(|name| {
                    let release = archive.strip_prefix(name)?.strip_prefix('-')?;
                    release
                        .starts_with(|first: char| first.is_ascii_digit())
                        .then_some((name, release))
                })
            })
            .ok_or_else(|| unexpected(line))?;
        if sha256.len() != 64 || !sha256.bytes().all(|byte| byte.is_ascii_hexdigit()) {
            return Err(unexpected(line));
        }
        if *version.get_or_insert(release) != release {
            return Err(ModuleError::new(
                "SHA256SUMS names more than one version".to_owned(),
            ));
        }
        archives.push((name, sha256.to_owned()));
    }
    let named: BTreeSet<&str> = archives.iter().map(|(name, _)| *name).collect();
    match version {
        Some(version) if archives.len() == PUBLISHED.len() && named.len() == PUBLISHED.len() => {
            Ok((version.to_owned(), archives))
        }
        _ => Err(ModuleError::new(format!(
            "SHA256SUMS must name each of {PUBLISHED:?} once"
        ))),
    }
}

/// A Git repository at `path` that commits whatever the container already holds there, as
/// beta.18's workspaces require.
fn repository(container: &Container, path: &str) -> Container {
    commit_all(
        &container
            .with_exec(vec!["git", "init", "--quiet", path])
            .with_workdir(path),
        "initialize workspace",
    )
}

/// Commits every change in the repository at the working directory.
fn commit_all(container: &Container, message: &str) -> Container {
    container
        .with_exec(vec!["git", "add", "--all"])
        .with_exec(vec![
            "git",
            "commit",
            "--quiet",
            "--allow-empty",
            "--message",
            message,
        ])
}

/// Runs `dagger <args>` connected to this engine as a new session.
fn dagger(container: &Container, args: &[&str]) -> Container {
    container.with_exec_opts(
        dagger_command(args),
        &ContainerWithExecOpts::default().with_dagger_in_dagger_new_session(true),
    )
}

/// The command line of `dagger <args>`.
fn dagger_command<'a>(args: &[&'a str]) -> Vec<&'a str> {
    let mut command = vec!["dagger"];
    command.extend_from_slice(args);
    command
}

/// Runs `dagger <args>` and checks what it prints, less the final newline.
async fn prints(container: &Container, args: &[&str], expected: &str) -> Result<(), ModuleError> {
    let output = dagger(container, args)
        .stdout()
        .await
        .map_err(step_failure)?;
    if output.trim_end() == expected {
        Ok(())
    } else {
        Err(check_failed(
            &format!("dagger {}", args.join(" ")),
            format!("printed {output:?}, not {expected:?}"),
        ))
    }
}

/// Runs `dagger <args>`, which must fail and say `reason`, and returns the container as
/// the failure left it.
async fn refused(
    container: &Container,
    args: &[&str],
    reason: &str,
) -> Result<Container, ModuleError> {
    let refusal = container.with_exec_opts(
        dagger_command(args),
        &ContainerWithExecOpts::default()
            .with_dagger_in_dagger_new_session(true)
            .with_expect(ReturnType::Failure),
    );
    let check = format!("dagger {}", args.join(" "));
    let output = refusal.combined_output().await.map_err(|error| {
        if let QueryError::Exec { error: exec, .. } = &error
            && exec.exit_code() == Some(0)
        {
            return check_failed(
                &check,
                format!(
                    "succeeded, but must fail:\n{}",
                    tail(exec.stdout().unwrap_or_default())
                ),
            );
        }
        step_failure(error)
    })?;
    if output.contains(reason) {
        Ok(refusal)
    } else {
        Err(check_failed(
            &check,
            format!("failed without saying {reason:?}:\n{}", tail(&output)),
        ))
    }
}

/// Checks that the repository at the working directory has no changes.
async fn unchanged(container: &Container, check: &str) -> Result<(), ModuleError> {
    let status = container
        .with_exec(vec!["git", "status", "--porcelain"])
        .stdout()
        .await
        .map_err(step_failure)?;
    if status.is_empty() {
        Ok(())
    } else {
        Err(check_failed(
            check,
            format!("changed the workspace:\n{status}"),
        ))
    }
}

/// The JSON document at `path` in `tree`.
async fn json_file(tree: &Directory, path: &str) -> Result<Value, ModuleError> {
    let text = tree.file(path).contents().await?;
    serde_json::from_str(&text).map_err(|error| ModuleError::new(format!("{path}: {error}")))
}

/// The string `key` of the JSON object read from `path`.
fn string_field<'a>(json: &'a Value, path: &str, key: &str) -> Result<&'a str, ModuleError> {
    json.get(key)
        .and_then(Value::as_str)
        .ok_or_else(|| ModuleError::new(format!("{path} has no string {key}")))
}

/// An acceptance check that ran but did not hold.
fn check_failed(check: &str, detail: impl std::fmt::Display) -> ModuleError {
    ModuleError::new(format!("{check}: {detail}"))
}

/// Reports a failed step with its command, exit code, and the end of its output. The
/// SDK's own conversion keeps only the engine's generic message for a failed execution,
/// and only "could not be built" for a query whose argument failed to resolve.
fn step_failure(error: QueryError) -> ModuleError {
    if let QueryError::Build(build) = &error
        && let Some(cause) =
            std::error::Error::source(build).and_then(|cause| cause.downcast_ref::<QueryError>())
    {
        return step_failure(cause.clone());
    }
    let QueryError::Exec { error: exec, .. } = &error else {
        return error.into();
    };
    let command = exec.command().unwrap_or_default().join(" ");
    let status = exec
        .exit_code()
        .map_or_else(String::new, |code| format!(" with exit code {code}"));
    let stdout = tail(exec.stdout().unwrap_or_default());
    let stderr = tail(exec.stderr().unwrap_or_default());
    ModuleError::new(format!("{command} failed{status}\n{stdout}\n{stderr}"))
}

/// The last `OUTPUT_TAIL` bytes of `output`, starting on a character boundary.
fn tail(output: &str) -> &str {
    let mut start = output.len().saturating_sub(OUTPUT_TAIL);
    while !output.is_char_boundary(start) {
        start += 1;
    }
    &output[start..]
}
